<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compliance e Habilitação | AssessorGov IA</title><style>:root{--bg:#07111f;--panel:#0d1b2d;--line:#243b58;--text:#f4f7fb;--muted:#aebed0;--accent:#7dd3fc;--ok:#36d399;--warn:#f6c453;--risk:#fb7185}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,Arial;background:var(--bg);color:var(--text)}.shell{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{padding:24px 18px;border-right:1px solid var(--line)}.brand{font-weight:900}.product{color:var(--accent);font-size:13px;margin:6px 0 28px}.nav a{display:block;color:var(--muted);text-decoration:none;padding:11px 12px;border-radius:10px;margin:4px 0}.nav a.active{background:#10243a;color:white}main{padding:28px;max-width:1300px}.muted{color:var(--muted)}.card{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:20px;margin-top:18px}.item{padding:18px 0;border-top:1px solid var(--line)}.item:first-child{border-top:0}.tag{display:inline-block;padding:5px 9px;border-radius:99px;font-size:12px;font-weight:800;border:1px solid var(--line)}.critical{color:var(--risk)}.high{color:var(--warn)}.opp{display:inline-block;margin:5px 5px 0 0;padding:6px 9px;border-radius:8px;background:#142a40;color:var(--muted);font-size:12px}.notice{padding:12px 14px;background:#10243a;border:1px solid var(--line);border-radius:10px;margin:18px 0}.btn{display:inline-block;text-decoration:none;color:#032016;background:var(--ok);padding:9px 12px;border-radius:9px;font-weight:800;font-size:13px}@media(max-width:800px){.shell{grid-template-columns:1fr}.side{display:none}}</style></head><body><div class="shell"><aside class="side"><div class="brand">VITRINE IA PRO</div><div class="product">AssessorGov IA</div><nav class="nav"><a href="/">Visão geral</a><a href="{{ route('gov.intelligence') }}">Inteligência Gov</a><a class="active" href="{{ route('gov.compliance') 